SEMANTIC_TO_IMAGE={
    'folder':'files', 'desktop':'desktop-folder', 'documents':'documents',
    'pictures':'pictures', 'music':'music', 'videos':'videos',
    'downloads':'downloads', 'home':'home', 'recent':'recent',
    'favorites':'favorites', 'trash':'trash', 'trash-full':'trash-full',
    'computer':'computer', 'network':'network', 'server':'server',
    'system-disk':'system-disk', 'disk':'data-disk', 'usb':'usb',
    'printer':'printer', 'browser':'browser', 'files':'files',
    'terminal':'terminal', 'mail':'mail', 'settings':'settings',
    'photos':'photos', 'office':'office', 'graphics':'graphics',
    'back':'back', 'forward':'next', 'up':'up', 'refresh':'refresh',
    'search':'search', 'new-folder':'folder-new', 'copy':'copy',
    'cut':'cut', 'paste':'paste', 'delete':'delete',
}

@lru_cache(maxsize=None)
def png_bytes(image_name: str) -> bytes:
    return base64.b85decode(ICON_PNG_BASE85[image_name])

@lru_cache(maxsize=None)
def svg_image(image_name: str) -> str:
    png=base64.b64encode(png_bytes(image_name)).decode('ascii')
    return ('<svg xmlns="http://www.w3.org/2000/svg" width="256" height="256" '
            'viewBox="0 0 256 256"><image x="0" y="0" width="256" '
            'height="256" href="data:image/png;base64,'+png+'"/></svg>')

def artwork(name: str, category: str, variant: str = 'light', size: int = 96) -> str | None:
    # Status/symbolic glyphs remain genuinely vector and contrast-aware.
    if category in ('panel', 'status', 'animations', 'emblems'):
        return None
    if name.endswith('-symbolic') or 'symbolic' in category:
        return None
    kind=resolve(name,category)
    if category=='places' and name=='folder': kind='folder'
    image=SEMANTIC_TO_IMAGE.get(kind)
    if not image: return None
    return svg_image(image)
